package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd
 */
public class MathUtils_gcd_TriageGen2Test {

    @Test
    public void testGcd_BothZero() {
        // gcd(0, 0) -> Math.abs(0) + Math.abs(0) = 0
        assertEquals(0, MathUtils.gcd(0, 0));
    }

    @Test
    public void testGcd_OneZero_Positive() {
        assertEquals(5, MathUtils.gcd(0, 5));
        assertEquals(5, MathUtils.gcd(5, 0));
        assertEquals(5, MathUtils.gcd(0, -5));
        assertEquals(5, MathUtils.gcd(-5, 0));
    }

    @Test(expected = RuntimeException.class)
    public void testGcd_Overflow_MinInt() {
        // If one is Integer.MIN_VALUE and other is 0, it should throw exception
        // because Math.abs(Integer.MIN_VALUE) overflows
        MathUtils.gcd(Integer.MIN_VALUE, 0);
    }

    @Test(expected = RuntimeException.class)
    public void testGcd_Overflow_MinInt_Other() {
        MathUtils.gcd(0, Integer.MIN_VALUE);
    }

    @Test
    public void testGcd_StandardPositive() {
        assertEquals(1, MathUtils.gcd(1, 1));
        assertEquals(6, MathUtils.gcd(12, 18));
        assertEquals(1, MathUtils.gcd(17, 13));
        assertEquals(5, MathUtils.gcd(10, 25));
    }

    @Test
    public void testGcd_NegativeInputs() {
        // The algorithm converts inputs to negative to handle the range
        assertEquals(6, MathUtils.gcd(-12, -18));
        assertEquals(6, MathUtils.gcd(-12, 18));
        assertEquals(6, MathUtils.gcd(12, -18));
        assertEquals(6, MathUtils.gcd(-12, 18));
    }

    @Test
    public void testGcd_PowersOfTwo() {
        // Tests the 'k' (cast out twos) logic
        assertEquals(4, MathUtils.gcd(4, 8));
        assertEquals(8, MathUtils.gcd(16, 8));
        assertEquals(2, MathUtils.gcd(2, 10));
    }

    @Test
    public void testGcd_LargePowersOfTwo_Overflow() {
        // If k reaches 31, it throws exception. 
        // 2^31 is not representable in a signed 32-bit int (max is 2^31 - 1)
        // We trigger this by having both numbers be multiples of 2^31 (not possible in int)
        // or through the specific logic flow. 
        // Since we can't input 2^31, we test the logic via the exception path if possible.
        // However, in standard int, the largest power of 2 is 2^30.
        // The code handles k < 31.
    }

    @Test
    public void testGcd_OddAndEven() {
        // B2/B3 logic: u is odd, v is even or vice versa
        assertEquals(3, MathUtils.gcd(9, 12)); // u=9 (odd), v=12 (even)
        assertEquals(3, MathUtils.gcd(12, 9)); // u=12 (even), v=9 (odd)
    }

    @Test
    public void testGcd_PrimeNumbers() {
        assertEquals(1, MathUtils.gcd(13, 17));
        assertEquals(1, MathUtils.gcd(19, 23));
    }

    @Test
    public void testGcd_OneIsOne() {
        assertEquals(1, MathUtils.gcd(1, 100));
        assertEquals(1, MathUtils.gcd(100, 1));
    }

    @Test
    public void testGcd_MaxInt() {
        // gcd(Integer.MAX_VALUE, 1) = 1
        assertEquals(1, MathUtils.gcd(Integer.MAX_VALUE, 1));
        // gcd(Integer.MAX_VALUE, Integer.MAX_VALUE) = Integer.MAX_VALUE
        assertEquals(Integer.MAX_VALUE, MathUtils.gcd(Integer.MAX_VALUE, Integer.MAX_VALUE));
    }
}
